function garageClose(){paused=false;$('garageOverlay').classList.add('hidden');last=performance.now()}
function renderGarage(){setRigUI();$('garageCoins').textContent=String(coins).padStart(3,'0');const vl=$('vehicleList'),ul=$('upgradeList');vl.innerHTML='<div class="garage-section-title">SELECT YOUR VEHICLE</div>';for(let i=0;i<rigs.length;i++){let r=rigs[i],item=document.createElement('div');item.className='garage-item'+(rigIndex===i?' selected':'');let action=owned[i]?(rigIndex===i?'EQUIPPED':'EQUIP'):`${r.price} ¢`;item.innerHTML=`<div class="rig-icon">${r.icon}</div><div class="garage-item-copy"><b>${r.name}</b><small>${r.klass}</small></div><button data-rig="${i}" ${!owned[i]&&coins<r.price?'disabled':''}>${action}</button>`;vl.appendChild(item)}ul.innerHTML='<div class="garage-section-title">PERFORMANCE UPGRADES</div>';for(const [key,s] of Object.entries(specs)){let level=upgrades[key]||0,cost=Math.floor(s.base*(1+level*.72)),item=document.createElement('div');item.className='garage-item upgrade-item';let action=level>=s.max?'MAXED':`${cost} ¢`;item.innerHTML=`<div class="rig-icon">${s.icon}</div><div class="garage-item-copy"><b>${s.name} <small>LV ${level}/${s.max}</small></b><small>${s.desc}</small></div><button data-upgrade="${key}" ${level>=s.max||coins<cost?'disabled':''}>${action}</button>`;ul.appendChild(item)}}
