import { createRequire } from 'node:module';
import { readFileSync, mkdirSync } from 'node:fs';
import { join } from 'node:path';
const runtime = join(process.env.HOME, '.local/share/omgithub-playwright');
const require = createRequire(join(runtime, 'package.json'));
const { chromium } = require('playwright');
const config = JSON.parse(readFileSync(join(process.env.RUNTIME_DIR, 'scripts/linux.json'), 'utf8'));
const browser = await chromium.launch(config.browser.launchOptions);
const page = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
page.on('pageerror', e => console.error('PAGEERROR', e.message));
await page.goto('http://localhost:3000', { waitUntil: 'load' });
await page.locator('#startButton').click({ force: true });
await page.waitForTimeout(3000);
mkdirSync('/tmp/overland-captures', { recursive: true });
await page.screenshot({ path: '/tmp/overland-captures/overland-latest.jpg', type: 'jpeg', quality: 88 });
await browser.close();

