8: const browser = await chromium.launch(config.browser.launchOptions);
9: const page = await browser.newPage({ viewport: { width: 1280, height: 800 }, deviceScaleFactor: 1 });
10: await page.addInitScript(() => { window.__frames=0; const raf=window.requestAnimationFrame.bind(window); window.requestAnimationFrame=cb=>raf(t=>{window.__frames++;cb(t)}); });
11: page.on('pageerror', e => console.error('PAGEERROR', e.message));
12: await page.goto('http://localhost:3000', { waitUntil: 'load' });
13: await page.locator('#startButton').click({ force: true });
14: await page.bringToFront();
15: await page.keyboard.down('ArrowRight');
16: await page.waitForTimeout(1000);
17: await page.waitForTimeout(3000);
18: await page.keyboard.up('ArrowRight');
19: console.log('distance',await page.locator('#distance').textContent(),'speed',await page.locator('#speed').textContent(),'state',await page.locator('#runState').textContent());
20: console.log('state', await page.locator('#runState').textContent(), 'status', await page.locator('#statusText').textContent());
21: await page.keyboard.press('g');
22: console.log('garage visible', await page.locator('#garageOverlay').evaluate(el => !el.classList.contains('hidden')));
23: await page.keyboard.press('g');
24: await page.waitForTimeout(500);
25: mkdirSync('/tmp/overland-captures', { recursive: true });
26: await page.screenshot({ path: '/tmp/overland-captures/overland-latest.jpg', type: 'jpeg', quality: 88 });
27: await browser.close();
